interface Row { id:number; entity:string; branch:string; account:string; policy:string; receipt:number; process:ProcessCode; errorCode:string; errorDescription:string; status:StatusCode; createdAt:string; auditAt:string; auditUser:string }
interface Movement { id:number; reconciliationId:number; process:ProcessCode; paymentAmount:number; operatedAmount:number; inputFileName:string; errorCode:string; errorDescription:string; originalDetail:string; reconciliationDescription:string; createdBy:string; createdAt:string; auditUser:string; auditAt:string }
interface MovementSummary { count:number; paymentAmount:number; operatedAmount:number; difference:number }
interface Contract { id:string; entity:string; branch:string; policy:string; customer:string; productId:string; renewalStatus:string; rimacStatus:ContractStatus; bankStatus:ContractStatus; createdAt:string; sourcePlatform:string }
