function renewalDailyTrend(rows:Row[],from:string,to:string){const grouped=new Map<string,{period:string;abiertas:number;resueltas:number}>();for(let date=new Date(`${from}T12:00:00`),end=new Date(`${to}T12:00:00`);date<=end;date.setDate(date.getDate()+1)){const period=date.toISOString().slice(0,10);grouped.set(period,{period,abiertas:0,resueltas:0})}rows.forEach(row=>{const created=row.createdAt.slice(0,10),opened=grouped.get(created);if(opened)opened.abiertas++;const audit=row.auditAt.slice(0,10),resolved=grouped.get(audit);if(row.status==='SOL'&&resolved)resolved.resueltas++});return [...grouped.values()]}
function rangeGranularity(from:string,to:string):'DAY'|'MONTH'|'YEAR'{const span=Math.max(0,(new Date(`${to}T12:00:00`).getTime()-new Date(`${from}T12:00:00`).getTime())/86400000);return span<=45?'DAY':span<=730?'MONTH':'YEAR'}
function contractTrend(rows:EnrichedContract[],granularity:'DAY'|'MONTH'|'YEAR'){const size=granularity==='DAY'?10:granularity==='MONTH'?7:4,grouped=new Map<string,{period:string;altas:number;formalizadas:number}>();rows.forEach(r=>{const key=r.createdAt.slice(0,size),current=grouped.get(key)||{period:key,altas:0,formalizadas:0};current.altas++;if(r.rimacStatus==='FOR')current.formalizadas++;grouped.set(key,current)});return [...grouped.values()].sort((a,b)=>a.period.localeCompare(b.period))}
